UPDATE CONTENT_AD_BANNER
   SET EXPOSE_YN = #{exposeYn},
       MDFCN_DT  = UTC_TIMESTAMP(6),
       MDFR_SN   = #{mdfrSn}
 WHERE CONTENT_AD_BANNER_SN = #{contentAdBannerSn}
   AND DEL_YN = 'N'

UPDATE CONTENT_AD_BANNER
   SET DEL_YN   = 'Y',
       MDFCN_DT = UTC_TIMESTAMP(6),
       MDFR_SN  = #{mdfrSn}
 WHERE CONTENT_AD_BANNER_SN = #{contentAdBannerSn}
   AND DEL_YN = 'N'
